-- IHLink SchoolPro MySQL migration draft 001
-- Target: MySQL 8.x / InnoDB / utf8mb4. Validate against the actual host before use.
-- SAFETY: TEST DATABASE ONLY. Never run against production or the current Supabase database.
-- This migration implements a core foundation, not every SchoolPro module.
-- IDs are generated by the application as UUID strings (CHAR(36)).

SET NAMES utf8mb4;
SET time_zone = '+00:00';

CREATE TABLE IF NOT EXISTS schema_migrations (
  version VARCHAR(100) NOT NULL,
  description VARCHAR(255) NOT NULL,
  applied_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS users (
  id CHAR(36) NOT NULL,
  email VARCHAR(320) NOT NULL,
  email_normalized VARCHAR(320) NOT NULL,
  display_name VARCHAR(160) NOT NULL,
  password_hash VARCHAR(255) NULL COMMENT 'Server-generated password hash only; never import Supabase secrets',
  status ENUM('pending','active','locked','disabled') NOT NULL DEFAULT 'pending',
  email_verified_at DATETIME(6) NULL,
  password_changed_at DATETIME(6) NULL,
  last_login_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email_normalized (email_normalized),
  KEY idx_users_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS user_sessions (
  id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  token_hash CHAR(64) NOT NULL COMMENT 'Hash of opaque session token; never store raw bearer token',
  expires_at DATETIME(6) NOT NULL,
  revoked_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  last_seen_at DATETIME(6) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_user_sessions_token_hash (token_hash),
  KEY idx_user_sessions_user_expiry (user_id, revoked_at, expires_at),
  CONSTRAINT fk_user_sessions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS platform_roles (
  user_id CHAR(36) NOT NULL,
  role_code VARCHAR(50) NOT NULL,
  granted_by CHAR(36) NULL,
  granted_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (user_id, role_code),
  KEY idx_platform_roles_role (role_code, user_id),
  CONSTRAINT fk_platform_roles_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_platform_roles_grantor FOREIGN KEY (granted_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS schools (
  id CHAR(36) NOT NULL,
  school_code VARCHAR(40) NOT NULL,
  name VARCHAR(200) NOT NULL,
  status ENUM('pending','active','suspended','archived') NOT NULL DEFAULT 'pending',
  timezone VARCHAR(64) NOT NULL DEFAULT 'Africa/Lagos',
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_schools_code (school_code),
  UNIQUE KEY uq_schools_id (id),
  KEY idx_schools_status_created (status, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS school_memberships (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  role_code VARCHAR(50) NOT NULL,
  status ENUM('invited','active','suspended','revoked') NOT NULL DEFAULT 'invited',
  position_title VARCHAR(120) NULL,
  invited_by CHAR(36) NULL,
  activated_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_membership_school_user (school_id, user_id),
  UNIQUE KEY uq_membership_school_id_pair (school_id, id),
  KEY idx_membership_user_status (user_id, status),
  KEY idx_membership_school_role_status (school_id, role_code, status),
  CONSTRAINT fk_membership_school FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT,
  CONSTRAINT fk_membership_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT,
  CONSTRAINT fk_membership_inviter FOREIGN KEY (invited_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS school_member_permissions (
  school_id CHAR(36) NOT NULL,
  membership_id CHAR(36) NOT NULL,
  permission_code VARCHAR(100) NOT NULL,
  granted BOOLEAN NOT NULL DEFAULT TRUE,
  granted_by CHAR(36) NULL,
  granted_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (membership_id, permission_code),
  KEY idx_member_permissions_school (school_id, permission_code, granted),
  CONSTRAINT fk_member_permissions_membership FOREIGN KEY (school_id, membership_id)
    REFERENCES school_memberships(school_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_member_permissions_grantor FOREIGN KEY (granted_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS academic_sessions (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  session_label VARCHAR(20) NOT NULL COMMENT 'Example: 2025/2026',
  starts_on DATE NULL,
  ends_on DATE NULL,
  is_current BOOLEAN NOT NULL DEFAULT FALSE,
  status ENUM('planned','active','closed') NOT NULL DEFAULT 'planned',
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_academic_session_school_label (school_id, session_label),
  UNIQUE KEY uq_academic_session_school_id (school_id, id),
  KEY idx_academic_sessions_current (school_id, is_current, status),
  CONSTRAINT fk_academic_sessions_school FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS academic_terms (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  session_id CHAR(36) NOT NULL,
  term_number TINYINT UNSIGNED NOT NULL,
  term_name VARCHAR(40) NOT NULL,
  starts_on DATE NULL,
  ends_on DATE NULL,
  status ENUM('planned','active','closed') NOT NULL DEFAULT 'planned',
  PRIMARY KEY (id),
  UNIQUE KEY uq_term_school_id (school_id, id),
  UNIQUE KEY uq_term_school_id_session (school_id, id, session_id),
  UNIQUE KEY uq_term_session_number (school_id, session_id, term_number),
  KEY idx_terms_session_status (school_id, session_id, status),
  CONSTRAINT fk_terms_session FOREIGN KEY (school_id, session_id)
    REFERENCES academic_sessions(school_id, id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS school_classes (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  class_name VARCHAR(80) NOT NULL,
  arm VARCHAR(40) NOT NULL DEFAULT '',
  education_level ENUM('nursery','primary','jss','sss','other') NOT NULL DEFAULT 'other',
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_classes_school_id (school_id, id),
  UNIQUE KEY uq_classes_name_arm (school_id, class_name, arm),
  KEY idx_classes_school_active (school_id, is_active, education_level),
  CONSTRAINT fk_classes_school FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS students (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  admission_number VARCHAR(80) NOT NULL,
  first_name VARCHAR(100) NOT NULL,
  middle_name VARCHAR(100) NULL,
  last_name VARCHAR(100) NOT NULL,
  date_of_birth DATE NULL,
  gender VARCHAR(30) NULL,
  status ENUM('active','inactive','graduated','transferred','withdrawn') NOT NULL DEFAULT 'active',
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_students_school_id (school_id, id),
  UNIQUE KEY uq_students_admission (school_id, admission_number),
  KEY idx_students_school_status_name (school_id, status, last_name, first_name),
  CONSTRAINT fk_students_school FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS student_enrollments (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  student_id CHAR(36) NOT NULL,
  session_id CHAR(36) NOT NULL,
  class_id CHAR(36) NOT NULL,
  status ENUM('active','completed','repeated','graduated','transferred') NOT NULL DEFAULT 'active',
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_enrollment_school_id (school_id, id),
  UNIQUE KEY uq_enrollment_school_id_session (school_id, id, session_id),
  UNIQUE KEY uq_enrollment_school_id_student_session (school_id, id, student_id, session_id),
  UNIQUE KEY uq_enrollment_student_session (school_id, student_id, session_id),
  KEY idx_enrollment_class_session_status (school_id, class_id, session_id, status),
  CONSTRAINT fk_enrollment_student FOREIGN KEY (school_id, student_id)
    REFERENCES students(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_enrollment_session FOREIGN KEY (school_id, session_id)
    REFERENCES academic_sessions(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_enrollment_class FOREIGN KEY (school_id, class_id)
    REFERENCES school_classes(school_id, id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS school_subjects (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  subject_code VARCHAR(50) NULL,
  subject_name VARCHAR(120) NOT NULL,
  education_level ENUM('nursery','primary','jss','sss','other') NOT NULL DEFAULT 'other',
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_subjects_school_id (school_id, id),
  UNIQUE KEY uq_subjects_school_name (school_id, subject_name, education_level),
  KEY idx_subjects_school_active (school_id, is_active, education_level),
  CONSTRAINT fk_subjects_school FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS class_subject_assignments (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  class_id CHAR(36) NOT NULL,
  subject_id CHAR(36) NOT NULL,
  membership_id CHAR(36) NULL,
  session_id CHAR(36) NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_class_subject_assignment (school_id, class_id, subject_id, session_id),
  UNIQUE KEY uq_class_subject_assignment_id (school_id, id),
  KEY idx_assignments_subject_session (school_id, subject_id, session_id, is_active),
  KEY idx_assignments_membership (school_id, membership_id, session_id),
  CONSTRAINT fk_csa_class FOREIGN KEY (school_id, class_id) REFERENCES school_classes(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_csa_subject FOREIGN KEY (school_id, subject_id) REFERENCES school_subjects(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_csa_session FOREIGN KEY (school_id, session_id) REFERENCES academic_sessions(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_csa_membership FOREIGN KEY (school_id, membership_id) REFERENCES school_memberships(school_id, id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS assessment_components (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  session_id CHAR(36) NOT NULL,
  term_id CHAR(36) NOT NULL,
  class_id CHAR(36) NOT NULL,
  subject_id CHAR(36) NOT NULL,
  component_code VARCHAR(40) NOT NULL,
  component_name VARCHAR(100) NOT NULL,
  max_score DECIMAL(7,2) NOT NULL,
  sequence_number SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_assessment_component_scope (school_id, id),
  UNIQUE KEY uq_assessment_component_school_id_session_term (school_id, id, session_id, term_id),
  UNIQUE KEY uq_assessment_component_code (school_id, session_id, term_id, class_id, subject_id, component_code),
  KEY idx_assessment_component_lookup (school_id, class_id, subject_id, session_id, term_id, is_active),
  CONSTRAINT fk_ac_session FOREIGN KEY (school_id, session_id) REFERENCES academic_sessions(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_ac_term_session FOREIGN KEY (school_id, term_id, session_id) REFERENCES academic_terms(school_id, id, session_id) ON DELETE RESTRICT,
  CONSTRAINT fk_ac_class FOREIGN KEY (school_id, class_id) REFERENCES school_classes(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_ac_subject FOREIGN KEY (school_id, subject_id) REFERENCES school_subjects(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_ac_class_subject_session FOREIGN KEY (school_id, class_id, subject_id, session_id)
    REFERENCES class_subject_assignments(school_id, class_id, subject_id, session_id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS result_records (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  enrollment_id CHAR(36) NOT NULL,
  subject_id CHAR(36) NOT NULL,
  session_id CHAR(36) NOT NULL,
  term_id CHAR(36) NOT NULL,
  total_score DECIMAL(7,2) NULL,
  grade VARCHAR(10) NULL,
  teacher_remark VARCHAR(500) NULL,
  status ENUM('draft','submitted','under_review','approved','published','correction_requested','locked') NOT NULL DEFAULT 'draft',
  created_by CHAR(36) NULL,
  updated_by CHAR(36) NULL,
  published_by CHAR(36) NULL,
  published_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_result_school_id (school_id, id),
  UNIQUE KEY uq_result_school_id_session_term (school_id, id, session_id, term_id),
  UNIQUE KEY uq_result_enrollment_subject_term (school_id, enrollment_id, subject_id, term_id),
  KEY idx_result_class_term_status (school_id, session_id, term_id, status),
  KEY idx_result_subject_term (school_id, subject_id, session_id, term_id, status),
  KEY idx_result_enrollment_term (school_id, enrollment_id, session_id, term_id),
  CONSTRAINT fk_result_enrollment_session FOREIGN KEY (school_id, enrollment_id, session_id) REFERENCES student_enrollments(school_id, id, session_id) ON DELETE RESTRICT,
  CONSTRAINT fk_result_subject FOREIGN KEY (school_id, subject_id) REFERENCES school_subjects(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_result_session FOREIGN KEY (school_id, session_id) REFERENCES academic_sessions(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_result_term_session FOREIGN KEY (school_id, term_id, session_id) REFERENCES academic_terms(school_id, id, session_id) ON DELETE RESTRICT,
  CONSTRAINT fk_result_creator FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_result_updater FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_result_publisher FOREIGN KEY (published_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS result_scores (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  result_id CHAR(36) NOT NULL,
  assessment_component_id CHAR(36) NOT NULL,
  session_id CHAR(36) NOT NULL,
  term_id CHAR(36) NOT NULL,
  score DECIMAL(7,2) NOT NULL,
  entered_by CHAR(36) NULL,
  updated_by CHAR(36) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_result_score_component (school_id, result_id, assessment_component_id),
  KEY idx_result_scores_component (school_id, assessment_component_id),
  CONSTRAINT fk_result_scores_result FOREIGN KEY (school_id, result_id, session_id, term_id) REFERENCES result_records(school_id, id, session_id, term_id) ON DELETE RESTRICT,
  CONSTRAINT fk_result_scores_component FOREIGN KEY (school_id, assessment_component_id, session_id, term_id) REFERENCES assessment_components(school_id, id, session_id, term_id) ON DELETE RESTRICT,
  CONSTRAINT fk_result_scores_entered_by FOREIGN KEY (entered_by) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_result_scores_updated_by FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS result_lifecycle_events (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  result_id CHAR(36) NOT NULL,
  event_type VARCHAR(50) NOT NULL,
  from_status VARCHAR(40) NULL,
  to_status VARCHAR(40) NULL,
  actor_user_id CHAR(36) NULL,
  reason VARCHAR(1000) NULL,
  snapshot JSON NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY idx_result_events_history (school_id, result_id, created_at),
  KEY idx_result_events_type_time (school_id, event_type, created_at),
  CONSTRAINT fk_result_events_result FOREIGN KEY (school_id, result_id) REFERENCES result_records(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_result_events_actor FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS attendance_records (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NOT NULL,
  enrollment_id CHAR(36) NOT NULL,
  attendance_date DATE NOT NULL,
  attendance_status ENUM('present','absent','late','excused') NOT NULL,
  note VARCHAR(500) NULL,
  marked_by CHAR(36) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_attendance_enrollment_date (school_id, enrollment_id, attendance_date),
  KEY idx_attendance_school_date (school_id, attendance_date, attendance_status),
  KEY idx_attendance_enrollment_date (school_id, enrollment_id, attendance_date),
  CONSTRAINT fk_attendance_enrollment FOREIGN KEY (school_id, enrollment_id) REFERENCES student_enrollments(school_id, id) ON DELETE RESTRICT,
  CONSTRAINT fk_attendance_marker FOREIGN KEY (marked_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS school_audit_events (
  id CHAR(36) NOT NULL,
  school_id CHAR(36) NULL,
  actor_user_id CHAR(36) NULL,
  action_code VARCHAR(100) NOT NULL,
  entity_type VARCHAR(100) NOT NULL,
  entity_id CHAR(36) NULL,
  request_id VARCHAR(100) NULL,
  ip_address VARBINARY(16) NULL,
  user_agent VARCHAR(500) NULL,
  before_snapshot JSON NULL,
  after_snapshot JSON NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY idx_audit_school_time (school_id, created_at),
  KEY idx_audit_actor_time (actor_user_id, created_at),
  KEY idx_audit_entity (entity_type, entity_id, created_at),
  CONSTRAINT fk_audit_school FOREIGN KEY (school_id) REFERENCES schools(id) ON DELETE RESTRICT,
  CONSTRAINT fk_audit_actor FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO schema_migrations (version, description)
VALUES ('001_schoolpro_core_draft', 'Draft core tenancy and academic/results schema; test environment only') AS incoming
ON DUPLICATE KEY UPDATE description = incoming.description;

-- Not yet included: guardians, fee ledger/receipts, subscriptions, result templates and workbook mappings,
-- report generation, admissions, CBT, assignments/submissions, notifications, storage metadata and all other modules.
-- These must be mapped from the live source schema before their migrations are authored.
